	if len(m.record.Keywords) > 0 {
		body.WriteString("\n\n")
		body.WriteString(m.styles.render(m.styles.sectionHeader, "KEYWORDS"))
		body.WriteString("\n")
		body.WriteString(strings.Join(m.record.Keywords, ", "))
